def require(condition, message):
    if not condition:
        raise ValueError(message)


def digest(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def text(path):
    path = Path(path).resolve(strict=True)
    SOURCE_FILES[str(path)] = digest(path)
    return path.read_text()


def read_json(path):
    return json.loads(text(path))


def route(sample):
    counters = sample['counters']
    return {'selections': sample['successfulSelections'],
        'counters': {key: counters[key] for key in ('irOpened', 'irRows', 'semanticNativeCompiles',
            'compiledBinds', 'interpretedBinds', 'aggregateCompiledBinds', 'aggregateInterpretedBinds')}}


def normalized(metadata):
    result = dict(metadata)
    for key in ('arm', 'source', 'store'):
        result.pop(key, None)
    result['jvmArguments'] = [v for v in result['jvmArguments']
        if not v.startswith('-D' + TRANSPORT + '=') and not v.startswith('-D' + MEMO + '=')]
    result['systemProperties'] = {k: v for k, v in result['systemProperties'].items() if k not in (TRANSPORT, MEMO)}
    return result


def sample_checks(sample, fixture_name, arm):
    fixture = FIXTURES[fixture_name]
    require(sample['type'] == 'sample' and sample['arm'] == arm and sample['consumption'] == 'full',
            'Sample identity/consumption mismatch')
    require(all(sample[key] for key in ('valid', 'complete', 'rowCountValid', 'checksumValid', 'partialMembershipValid'))
        and sample['rows'] == fixture['rows'] and sample['checksum'] == fixture['checksum']
        and sample['expectedFullChecksum'] == fixture['checksum']
        and sample['bindingReads'] == fixture['rows'] * len(fixture['names'])
        and sample['retainedRows'] == 0, 'Independent result oracle record failed')
    if fixture_name == 'shared-tail':
        require(sample['exactBagValid'], 'Exact shared-tail bag oracle failed')
    require(sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0 and sample['ledgerReleased'],
            'Nonzero query-ledger endpoint')
    require(all(isinstance(sample[key], int) and sample[key] >= 0 for key in METRICS)
        and sample['totalNs'] > 0 and sample['allThreadAllocatedBytes'] > 0, 'Invalid timing/allocation metric')
    require(sample['autoRequested'] and sample['auto'] and sample['successfulSelections']
        and not any('forced' in selection['mode'] for selection in sample['successfulSelections']),
        'Normal AUTO not observed')
    counters = sample['counters']
    require(counters['irOpened'] == counters['semanticNativeCompiles'] == 1
        and counters['irRows'] == fixture['rows'] and counters['lazyValueCalls'] >= 0,
        'Native IR/resolver counter mismatch')
    admission = counters['coordinateAdmissions']
    require(admission['opened'] == (1 if arm == 'dense' else 0)
        and admission['initialAdmissionRefused'] == admission['growthAdmissionRefused'] == 0,
        'Coordinate-owner admission changed')
    if sample['stage'] == 'measurement':
        require(counters['compiledBinds'] == 1 and counters['interpretedBinds']
            == counters['aggregateCompiledBinds'] == counters['aggregateInterpretedBinds'] == 0,
            'Measured query did not use compiled-only native IR')
    adjacency = sample['adjacency']
    require(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE' and adjacency['lookupHits'] > 0
        and adjacency['currentRevisionBefore'] == adjacency['appliedRevisionBefore']
        == adjacency['currentRevisionAfter'] == adjacency['appliedRevisionAfter'],
        'Query-time adjacency state/revision/use changed')


def read_accounting(folder, fixture_name, arm, samples):
    records = [json.loads(line) for line in text(folder / 'direct-memo-statistics.jsonl').splitlines() if line.strip()]
    count = 13 if arm == 'direct' else 0
    require(len(records) == count + 1, 'Direct-memo owner count differs from treatment')
    header = records.pop(0)
    require(header['format'] == 1 and header['type'] == 'memoStatisticsMetadata'
        and header['scope'] == ACCOUNTING_SCOPE and header['fixture'] == fixture_name
        and header['delegateLauncher'] == FIXTURES[fixture_name]['launcher']
        and header['harnessReturned'] and header['harnessFailureClass'] is None,
        'Statistics wrapper identity or completion differs')
    require(header['capacity'] == 13 and [header[k] for k in ('opened', 'closed', 'size')] == [count] * 3
        and header['overflowCount'] == 0, 'Direct-memo lifecycle count or buffer overflow')
    require([record['recordIndex'] for record in records] == list(range(count)), 'Statistics record order differs')
    previous = None
    for index, record in enumerate(records):
        sample = samples[index]
        require(set(record) == {'type', 'recordIndex', *OWNER_FIELDS} and record['type'] == 'owner'
            and all(type(record[key]) is int and record[key] >= 0 for key in OWNER_FIELDS),
            'Invalid scalar owner record')
        require(all(record[key] == index + 1 for key in
            ('ownerOrdinal', 'compileOrdinalAtOpen', 'compileOrdinalAtClose')),
            'Direct-memo lifetime cannot align one-to-one with semantic compilation')
        require(previous is None or record['lazyValueCallsAtOpen'] == previous,
            'Resolution happened in an inter-owner gap')
        require(record['lazyValueCallsAtClose'] - record['lazyValueCallsAtOpen']
            == sample['counters']['lazyValueCalls'], 'Owner interval differs from original raw resolver count')
        previous = record['lazyValueCallsAtClose']
        require(record['probes'] > 0 and record['hits'] + record['collisions'] <= record['probes'],
            'Hits and collisions exceed probes')
        require(not any(record[key] for key in FORBIDDEN_EVENTS),
            'Unexpected invalidation, unsupported value, rehash collision, refusal, or outstanding array charge')
        require(record['resizes'] <= 4 and record['peakCapacity'] == 4096 * (2 ** record['resizes']),
            'Capacity cannot be produced by the reported successful resizes')
        require(not record['resizes'] or record['probes'] // 8192 >= record['resizes'] + 1,
            'Successful resizes exceed available post-cutoff probe boundaries')
        capacity = record['peakCapacity']
        charge = 80 + 36 * capacity + (80 + 36 * (capacity // 2) if record['resizes'] else 0)
        require(record['peakArrayBytes'] == charge <= sample['ledgerPeakBytes'],
            'Array reservation peak does not reconcile with the capacity or query ledger')
        require(record['capacityAtClose'] in (0, capacity)
            and record['retainedEntriesAtClose'] <= record['capacityAtClose'], 'Invalid retained table occupancy')
        disabled = record['lowHitDisable']
        require(disabled in (0, 1) and record['disabledAtClose'] == disabled,
            'Disabled state is not explained by the first-window cutoff')
        if disabled:
            require(record['probes'] == 8192 and record['hits'] < 2048
                and record['resizes'] == record['capacityAtClose'] == record['retainedEntriesAtClose'] == 0,
                'Low-hit disable violates its first-window necessary conditions')
        else:
            require(record['capacityAtClose'] == capacity
                and (record['probes'] < 8192 or record['hits'] >= 2048),
                'Active table fails a necessary first-window or capacity condition')
        record.update({'iteration': sample['iteration'], 'stage': sample['stage'],
            'rawResolverCalls': sample['counters']['lazyValueCalls']})
    return {'header': header, 'records': records, 'qualified': True}


def read_fork(folder, fixture_name, arm, round_index, fixture_position, arm_position, protocol, cp):
    fixture = FIXTURES[fixture_name]
    command = read_json(folder / 'command.json')
    process = read_json(folder / 'process-result.json')
    records = [json.loads(line) for line in text(folder / 'samples.jsonl').splitlines() if line.strip()]
    audit = read_json(folder / 'root-host-audit.json')
    require(len(records) == 14 and records[0]['type'] == 'metadata', 'Expected metadata and all thirteen query records')
    metadata, samples = records[0], records[1:]
    mode = 'dense' if arm == 'dense' else 'off'
    memo = 'true' if arm == 'direct' else 'false'
    jvm = JVM + ['-D' + TRANSPORT + '=' + mode, '-D' + MEMO + '=' + memo]
    expected_command = [JAVA, *jvm, '-cp', cp, QUALIFIED_LAUNCHER, fixture_name, '--arm=' + arm,
        '--source=' + protocol['runtime']['sourceIdentity'], '--warmup=8', '--iterations=5',
        *fixture['arguments'], '--consumption=full', '--output=' + str(folder / 'samples.jsonl'),
        '--store=' + str(folder / 'store')]
    repo = Path(protocol['driverFile']).resolve().parents[3]
    require(command['argv'] == expected_command and command['cwd'] == str(repo), 'Exact fork command differs')
    require(process['exitCode'] == 0 and process['failure'] is None
        and process['startedEpochNs'] == command['startedEpochNs']
        and process['finishedEpochNs'] >= process['startedEpochNs'], 'Process failed or interval invalid')
    expected_metadata = {**CONFIG, **fixture['metadata'], 'arm': arm,
        'source': protocol['runtime']['sourceIdentity'], 'consumption': 'full',
        'projectedNames': fixture['names'], 'expectedRows': fixture['rows'],
        'expectedChecksum': fixture['checksum'], 'maxHeapBytes': 1073741824,
        'warmup': 8, 'measurementsToRun': 5, 'javaVersion': '25.0.5+8-LTS',
        'namespaceExperimentHarness': 'native-and-direct-adjacency-v1', 'jvmArguments': jvm,
        'systemProperties': {'rdf4j.lmdb.hotCounters': 'true', BUDGET: '536870912',
                             TRANSPORT: mode, MEMO: memo}}
    require(all(metadata.get(k) == v for k, v in expected_metadata.items()), 'Observed fixture/JVM/source configuration differs')
    setup = metadata['adjacencySetup']
    require(setup['state'] == 'ACTIVE' and setup['currentRevisionReady']
        and setup['appliedRevision'] == setup['currentDataRevision'], 'Adjacency setup not ready')
    require([s['iteration'] for s in samples] == list(range(-8, 5))
        and [s['stage'] for s in samples] == ['warmup'] * 8 + ['measurement'] * 5,
        'Warmup/measurement count or chronology differs')
    for sample in samples:
        sample_checks(sample, fixture_name, arm)
        require(sample['adjacency']['currentRevisionBefore'] == setup['currentDataRevision'],
                'Query adjacency differs from setup revision')
    require(audit['type'] == 'root-host-audit' and audit['format'] == 1
        and audit['harnessReturned'] and audit['harnessFailureClass'] is None
        and audit['hostedGenericTotal'] == 0 and audit['semanticNativeCompilesTotal'] == 13
        and audit['harnessMain'] == fixture['main'] and audit['readPhase'] == fixture['readPhase'],
        'Outer-root/native-compile reconciliation failed')
    accounting = read_accounting(folder, fixture_name, arm, samples)
    measured = samples[8:]
    histogram = Counter(json.dumps(route(s), sort_keys=True) for s in measured)
    return {'fixture': fixture_name, 'round': round_index, 'fixturePosition': fixture_position,
        'armPosition': arm_position, 'arm': arm, 'folder': str(folder), 'command': command,
        'process': process, 'metadata': metadata, 'rootAudit': audit, 'accounting': accounting,
        'samples': samples, 'measurementMedians': {metric: statistics.median(s[metric] for s in measured) for metric in METRICS},
        'coldFirstQuery': {metric: samples[0][metric] for metric in METRICS},
        'measuredRouteHistogram': dict(histogram),
        'measuredResolverCalls': [s['counters']['lazyValueCalls'] for s in measured],
        'measuredAdjacencyLookupHits': [s['adjacency']['lookupHits'] for s in measured]}


def ratios_for(runs, value_field):
    indexed = {(r['fixture'], r['round'], r['arm']): r for r in runs}
    output = []
    for fixture in FIXTURES:
        for numerator, denominator in COMPARISONS:
            per_round = []
            for index in range(6):
                a, b = indexed[fixture, index, numerator][value_field], indexed[fixture, index, denominator][value_field]
                per_round.append({'round': index, 'ratios': {
                    metric: a[metric] / b[metric] if b[metric] else None for metric in METRICS}})
            vectors = {metric: [p['ratios'][metric] for p in per_round if p['ratios'][metric] is not None]
                       for metric in METRICS}
            output.append({'fixture': fixture, 'numerator': numerator, 'denominator': denominator,
                'perRound': per_round,
                'medianRatios': {metric: statistics.median(values) if values else None for metric, values in vectors.items()},
                'ratioRanges': {metric: [min(values), max(values)] if values else None for metric, values in vectors.items()},
                'ratiosBelowOne': {metric: sum(value < 1 for value in values) for metric, values in vectors.items()}})
    return output


def total_effect_screen(comparisons, treatment_pairs):
    screens = []
    for comparator in ('ordinary', 'dense'):
        gates = [{'name': '312 treatment query pairs preserve route and adjacency observations',
                  'passed': len(treatment_pairs) == 312 and all(p['passed'] for p in treatment_pairs)}]
        for fixture in FIXTURES:
            result = next(v for v in comparisons if v['fixture'] == fixture
                          and v['numerator'] == 'direct' and v['denominator'] == comparator)
            latency = [p['ratios']['totalNs'] for p in result['perRound']]
            allocation = [p['ratios']['allThreadAllocatedBytes'] for p in result['perRound']]
            gates += [
                {'name': fixture + ' median latency ratio <=0.95', 'passed': statistics.median(latency) <= 0.95,
                 'observed': statistics.median(latency)},
                {'name': fixture + ' every latency ratio <1', 'passed': all(v < 1 for v in latency), 'observed': latency},
                {'name': fixture + ' median allocation ratio <=1', 'passed': statistics.median(allocation) <= 1,
                 'observed': statistics.median(allocation)},
                {'name': fixture + ' every allocation ratio <=1.02', 'passed': max(allocation) <= 1.02,
                 'observed': allocation}]
        screens.append({'candidate': 'direct', 'comparator': comparator,
                       'passed': all(g['passed'] for g in gates), 'gates': gates})
    return {'bothPassed': all(screen['passed'] for screen in screens), 'screens': screens,
        'interpretation': 'Separate fixed engineering screens; no statistical significance or production promotion. Retained Value payload remains outside the array charge.'}


def analyze(protocol_path, comparison, expected_protocol_sha):
    protocol = read_json(protocol_path)
    require(digest(protocol_path) == expected_protocol_sha, 'Frozen protocol hash differs from supplied freeze receipt')
    require(digest(__file__) == protocol['independentAnalysisFileSha256'],
        'Independent analysis code changed after protocol freeze')
    require(text(comparison / 'used-protocol.json') == Path(protocol_path).read_text(), 'Consumed protocol differs')
    require(protocol['arms'] == ARMS and protocol['balancedOrders'] == ORDERS
        and protocol['fixtureOrdersByRound'] == FIXTURE_ORDERS
        and protocol['rounds'] == 6 and protocol['warmup'] == 8 and protocol['iterations'] == 5
        and protocol['java'] == JAVA and protocol['jvmArguments'] == JVM
        and protocol['configuration'] == CONFIG and protocol['qualifiedLauncher'] == QUALIFIED_LAUNCHER,
        'Prespecified timing design changed')
    screen = protocol['totalEffectScreen']
    require(screen['medianLatencyMaximumRatioEachFixture'] == 0.95 and screen['everyLatencyRatioStrictlyBelowOne']
        and screen['medianAllocationMaximumRatioEachFixture'] == 1.0
        and screen['individualAllocationMaximumRatioEitherFixture'] == 1.02
        and screen['rawResolverEqualityRequired'] is False
        and protocol['directMemoAccountingPolicy']['scope'] == ACCOUNTING_SCOPE
        and protocol['directMemoAccountingPolicy']['fields'] == list(OWNER_FIELDS)
        and protocol['directMemoAccountingPolicy']['zeroRequiredFields'] == list(FORBIDDEN_EVENTS),
        'Prespecified total-effect or accounting criteria changed')
    require(screen['primaryComparisons'] == [['direct', 'ordinary'], ['direct', 'dense']]
        and protocol['directMemoPolicy']['variant'] == 'identity-witness-v1'
        and protocol['directMemoPolicy']['initialCapacity'] == 4096
        and protocol['directMemoPolicy']['maximumCapacity'] == 65536
        and protocol['directMemoPolicy']['probeInterval'] == 8192, 'Memo variant or adaptive limits changed')
    runtime = read_json(protocol['runtimeDescriptorFile'])
    require(runtime == protocol['runtime'] and digest(protocol['runtimeDescriptorFile']) == protocol['runtimeDescriptorFileSha256'],
            'Runtime descriptor differs from the frozen protocol')
    cp = text(runtime['classpathFile']).strip()
    require(digest(runtime['classpathFile']) == runtime['classpathFileSha256'], 'Classpath command text changed')
    expected_directories, runs = [], []
    metadata_references, route_references = {}, {}
    previous_end = None
    for round_index, order in enumerate(ORDERS):
        for fixture_position, fixture in enumerate(FIXTURE_ORDERS[round_index]):
            for arm_position, arm in enumerate(order):
                name = f'round-{round_index:02d}-{fixture_position:02d}-{fixture}-{arm_position:02d}-{arm}'
                expected_directories.append(name)
                run = read_fork(comparison / name, fixture, arm, round_index, fixture_position, arm_position, protocol, cp)
                if previous_end is not None:
                    require(run['process']['startedEpochNs'] >= previous_end, 'Recorded timing JVM intervals overlap')
                previous_end = run['process']['finishedEpochNs']
                metadata = normalized(run['metadata'])
                if fixture not in metadata_references:
                    metadata_references[fixture] = metadata
                    route_references[fixture] = run['measuredRouteHistogram']
                require(metadata == metadata_references[fixture], 'Normalized fixture/JVM metadata differs within fixture')
                require(run['measuredRouteHistogram'] == route_references[fixture], 'Measured route histogram differs within fixture')
                runs.append(run)
    actual_directories = {p.name for p in comparison.glob('round-*') if p.is_dir()}
    require(actual_directories == set(expected_directories), 'Missing or additional timing fork directory')
    indexed = {(r['fixture'], r['round'], r['arm']): r for r in runs}
    treatment_pairs = []
    for fixture in FIXTURES:
        for index in range(6):
            direct = indexed[fixture, index, 'direct']
            for comparator in ('ordinary', 'dense'):
                reference = indexed[fixture, index, comparator]
                for a, b in zip(reference['samples'], direct['samples'], strict=True):
                    require(a['iteration'] == b['iteration'] and a['stage'] == b['stage'],
                        'Treatment query alignment differs')
                    same = route(a) == route(b) and a['adjacency'] == b['adjacency']
                    treatment_pairs.append({'fixture': fixture, 'round': index, 'comparator': comparator,
                        'iteration': a['iteration'], 'stage': a['stage'],
                        'referenceResolverCalls': a['counters']['lazyValueCalls'],
                        'directResolverCalls': b['counters']['lazyValueCalls'],
                        'rawResolverDifferenceDirectMinusReference': b['counters']['lazyValueCalls'] - a['counters']['lazyValueCalls'],
                        'rawResolverEqualityRequired': False,
                        'referenceRoute': route(a), 'directRoute': route(b), 'referenceAdjacency': a['adjacency'],
                        'directAdjacency': b['adjacency'], 'passed': same})
    require(len(treatment_pairs) == 312 and all(v['passed'] for v in treatment_pairs),
        'Treatment per-query route and adjacency matching failed')
    require(len(runs) == 36 and sum(len(r['samples']) for r in runs) == 468,
            'Prespecified fresh-JVM/query count mismatch')
    comparisons = ratios_for(runs, 'measurementMedians')
    descriptive = {}
    for fixture in FIXTURES:
        descriptive[fixture] = {}
        for arm in ARMS:
            forks = [r for r in runs if r['fixture'] == fixture and r['arm'] == arm]
            descriptive[fixture][arm] = {'medianOfSixJvmMedians': {
                key: statistics.median(r['measurementMedians'][key] for r in forks) for key in METRICS},
                'jvmMediansByRound': [{'round': r['round'], 'metrics': r['measurementMedians']} for r in forks],
                'resolverCallsObserved': sorted({s['counters']['lazyValueCalls'] for r in forks for s in r['samples']}),
                'memoStatisticsByStage': {stage: {
                    'owners': sum(owner['stage'] == stage for r in forks for owner in r['accounting']['records']),
                    'sums': {key: sum(owner[key] for r in forks for owner in r['accounting']['records']
                        if owner['stage'] == stage) for key in OWNER_FIELDS[5:]},
                    'observed': {key: sorted({owner[key] for r in forks for owner in r['accounting']['records']
                        if owner['stage'] == stage}) for key in OWNER_FIELDS[5:]}}
                    for stage in ('warmup', 'measurement')},
                'measuredAdjacencyLookupHitsObserved': sorted({x for r in forks for x in r['measuredAdjacencyLookupHits']})}
    require(all(digest(path) == expected for path, expected in SOURCE_FILES.items()), 'Raw input changed during independent analysis')
    return {'format': 1, 'valid': True, 'complete': True, 'protocolSha256': expected_protocol_sha,
        'analysisScriptSha256': digest(__file__), 'sourceFiles': SOURCE_FILES,
        'independentImplementation': 'Python stdlib only; no runner imports, runs.json, or summary.json inputs',
        'freshJvms': 36, 'queries': 468, 'warmupQueries': 288, 'measuredQueries': 180,
        'matchedTreatmentQueryPairs': 312, 'serialProcessIntervals': True,
        'ratioDefinition': 'Ratio of medians of all five measured queries per fresh JVM, paired by fixture and round; median and full range of six ratios.',
        'descriptiveArmStatistics': descriptive, 'comparisons': comparisons,
        'coldFirstQueryComparisons': ratios_for(runs, 'coldFirstQuery'),
        'coldScope': 'First query after fixture/store setup; excludes JVM launch and fixture construction. All eight warmups remain retained.',
        'treatmentQueryPairs': treatment_pairs, 'runs': runs, 'totalEffectEvidence': total_effect_screen(comparisons, treatment_pairs),
        'resultAndRouteQualification': 'All prescribed raw result flags/counts/checksums, shared exact-bag oracle records, normal AUTO/native routes, coordinate admissions, active adjacency, root audits, ledger endpoints, direct-owner alignment, adaptive accounting invariants, and zero unexpected invalidation/unsupported-value/refusal gates passed.',
        'identityScope': 'Observed source metadata and exact launch commands match the frozen runtime descriptor/classpath. Full compiled-artifact byte preservation is checked separately by the experiment runtime verifier.',
        'limitations': ['Six paired fresh JVMs per arm and fixture; not a population confidence interval.',
            'The direct arm changes hashing, transport, strong retention, and adaptation together; individual mechanisms are not causally isolated.',
            'The timed identity-witness variant has a fifth array beyond the four-array sketch; archived correctness evidence explains this strengthening.',
            'Array-only charges omit retained Value payload and ownership graphs, including later lazy initialization. Ledger peaks do not bound live heap.',
            'Raw resolver differences and low-hit disabling are outcomes. No count gate or algebraic timing/allocation normalization is applied.',
            'Direct adaptive counters and primitive lifecycle exports are included in measured cost; control arms create no direct owners. This study does not estimate observer overhead separately.',
            'No new dense factor-page refusal counter was added; original coordinate-owner admission counters and the preserved configuration are checked.',
            'Full consumption at 512 MiB per-query limit; no latency inference to delayed repetition, early close, retained rows, constrained budgets, or different projection/uniqueness distributions.']}



def report(data):
    lines = ['# Independent direct-memo timing analysis', '',
        'This analysis recomputed the frozen study from raw samples, direct-memo owner records, commands, process results, and root audits. It imported no experiment code and did not read the driver results or summary.', '',
        f"All **{data['freshJvms']} fresh JVMs**, **{data['queries']} queries** ({data['warmupQueries']} warmups and {data['measuredQueries']} measurements), and **{data['matchedTreatmentQueryPairs']} treatment query pairs** passed independent validation.", '',
        'The primary outcome is total query cost under natural GC. Strong retention, direct-map bookkeeping, adaptation, coordinate transport differences, and resolver changes are included. No event-based correction or sample exclusion is applied.', '',
        '## Measured comparisons', '',
        'Each JVM contributes the median of all five measurements. Ratios pair the same fixture and round; below one favors the numerator. All six pairs contribute to the median and full range. Fixtures and historical studies are not pooled.', '',
        '| Fixture | Ratio | Latency median [range] | Allocation median [range] | Preparation median [range] | Ledger peak median [range] |',
        '|---|---|---:|---:|---:|---:|']
    def form(entry, metric):
        value, span = entry['medianRatios'][metric], entry['ratioRanges'][metric]
        return 'undefined' if value is None else f'{value:.6f} [{span[0]:.6f}, {span[1]:.6f}]'
    for entry in data['comparisons']:
        lines.append('| ' + entry['fixture'] + ' | ' + entry['numerator'] + ' / ' + entry['denominator'] + ' | '
            + ' | '.join(form(entry, key) for key in ('totalNs', 'allThreadAllocatedBytes', 'prepareNs', 'ledgerPeakBytes')) + ' |')
    lines += ['', '## Every primary latency ratio', '',
        '| Fixture | Comparison | Round1 | Round2 | Round3 | Round4 | Round5 | Round6 |',
        '|---|---|---:|---:|---:|---:|---:|---:|']
    for entry in data['comparisons']:
        if entry['numerator'] == 'direct':
            lines.append('| ' + entry['fixture'] + ' | direct / ' + entry['denominator'] + ' | '
                + ' | '.join(f"{p['ratios']['totalNs']:.9f}" for p in entry['perRound']) + ' |')
    lines += ['', '## Absolute observations', '',
        'These are medians of six JVM medians. Ratios of table entries are not the paired estimator above. Allocation uses decimal GB; ledger peaks use MiB. The direct ledger omits retained Value payload, so its peak is not a live-heap bound.', '',
        '| Fixture | Arm | Seconds | All-thread allocation GB | Preparation ms | Ledger peak MiB | Raw resolver calls/query |',
        '|---|---|---:|---:|---:|---:|---|']
    for fixture, arms in data['descriptiveArmStatistics'].items():
        for arm, entry in arms.items():
            m = entry['medianOfSixJvmMedians']
            lines.append(f"| {fixture} | {arm} | {m['totalNs']/1e9:.6f} | {m['allThreadAllocatedBytes']/1e9:.6f} | "
                + f"{m['prepareNs']/1e6:.6f} | {m['ledgerPeakBytes']/1048576:.6f} | "
                + ', '.join(f'{v:,}' for v in entry['resolverCallsObserved']) + ' |')
    lines += ['', '## Direct-map behavior', '',
        'Counts cover all retained queries in each stage. Ordinary and dense create no direct-memo owner. Low-hit disabling is a valid adaptive outcome. Hits count validated table candidates; standalone access may still resolve a candidate to preserve source ownership handoff, while outward capture passes its actual exposure token. Hits are not generally resolver calls avoided. The full per-owner 22-field records and authoritative raw resolver counts are retained in JSON.', '',
        '| Fixture | Stage | Owners | Probes | Hits | Collisions | Low-hit disables | Successful resizes | Peak capacities observed | Peak array charges observed |',
        '|---|---|---:|---:|---:|---:|---:|---:|---|---|']
    for fixture, arms in data['descriptiveArmStatistics'].items():
        for stage, entry in arms['direct']['memoStatisticsByStage'].items():
            c, observed = entry['sums'], entry['observed']
            lines.append(f"| {fixture} | {stage} | {entry['owners']} | {c['probes']} | {c['hits']} | "
                + f"{c['collisions']} | {c['lowHitDisable']} | {c['resizes']} | "
                + ', '.join(str(v) for v in observed['peakCapacity']) + ' | '
                + ', '.join(str(v) for v in observed['peakArrayBytes']) + ' |')
    lines += ['', '## Prespecified engineering screens', '',
        'The screen is evaluated separately against each comparator. It requires a median latency ratio at most 0.95 on both fixtures, all six latency ratios below one in each fixture, median allocation at most one, and no allocation pair above 1.02. These are engineering thresholds, not a significance test. Incomplete retained-payload accounting prevents production promotion even if both screens pass.']
    for screen in data['totalEffectEvidence']['screens']:
        lines += ['', '### Direct versus ' + screen['comparator'], '',
            '**' + ('Passed.' if screen['passed'] else 'Did not pass.') + '**', '',
            '| Criterion | Result | Observed |', '|---|---|---|']
        for gate in screen['gates']:
            value = gate.get('observed', '312 / 312 matched')
            if isinstance(value, list):
                value = ', '.join(f'{v:.9f}' for v in value)
            elif isinstance(value, float):
                value = f'{value:.9f}'
            lines.append(f"| {gate['name']} | {'pass' if gate['passed'] else 'fail'} | {value} |")
    lines += ['', '## First-query observations', '',
        'The first query follows fixture construction, excludes JVM launch and fixture setup, and is not used by the warm-latency screen. All eight warmups remain preserved.', '',
        '| Fixture | Ratio | First-query total median [range] | First-query preparation median [range] |',
        '|---|---|---:|---:|']
    for entry in data['coldFirstQueryComparisons']:
        lines.append('| ' + entry['fixture'] + ' | ' + entry['numerator'] + ' / ' + entry['denominator']
            + ' | ' + form(entry, 'totalNs') + ' | ' + form(entry, 'prepareNs') + ' |')
    lines += ['', '## Qualification and limits', '',
        'All raw result, checksum, exact shared-tail bag, active-adjacency, normal AUTO, native compiled-tier, root-host, and ledger endpoint gates passed. Direct owners align through semantic-compilation ordinals and cumulative resolver intervals. Both comparator pairs preserve per-query routes and complete adjacency observations, including warmups. Raw resolver differences remain visible in the JSON receipt.', '',
        'Every direct owner passes the necessary aggregate probe/collision/capacity invariants, earliest possible growth-boundary check, exact charged array-peak calculation, and zero final array-charge gate. Rehash collision discards are zero, as required by fixed-hash power-of-two doubling. Invalidations, unsupported values, and direct table admission refusals are zero on these fixtures. Those checks supplement the sealed correctness contracts; aggregate final counts alone cannot replay every adaptive boundary. Original coordinate-owner admission refusals are also zero. No new observer claims to measure dense factor-page refusal.', '',
        'The matched runtime retains the original fifteen-class harness and adds the same six-class prefix for all arms. The timed variant has a fifth identity-witness array beyond the four-array proposal. This avoids accepting a value whose internal revision changed without a semantic-version bump. The collector stores primitives at lifecycle boundaries and serializes only after the original launcher returns. These costs are part of the measured implementation.', '',
        'The direct strategy retains strong values. Array charges exclude their object graphs and later lexical initialization. Therefore allocation and ledger reductions do not establish a retained-heap bound. The comparison does not isolate strong retention from hashing or removal of coordinate transport.', '',
        'The fixed full-consumption fixtures do not establish performance for delayed repetition, early close, retained rows, long payloads, other projections, high uniqueness, or constrained memory. Six paired JVMs are a bounded engineering observation; no population confidence interval is claimed. No historical, diagnostic, preflight, or incomplete timing is pooled.', '',
        f"Frozen protocol SHA-256: `{data['protocolSha256']}`.", '',
        f"Independent analysis SHA-256: `{data['analysisScriptSha256']}`.", '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--protocol', type=Path, required=True)
    parser.add_argument('--comparison', type=Path, required=True)
    parser.add_argument('--expected-protocol-sha256', required=True,
        help='Exact SHA-256 printed by the pre-timing freeze command; do not derive it from modified analysis inputs')
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--post-timing-slot-released', action='store_true')
    args = parser.parse_args()
    require(args.post_timing_slot_released, 'Coordinator must release the post-timing analysis slot')
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    try:
        require(len(args.expected_protocol_sha256) == 64
            and all(c in '0123456789abcdef' for c in args.expected_protocol_sha256), 'Invalid frozen protocol SHA-256')
        result = analyze(args.protocol.resolve(strict=True), args.comparison.resolve(strict=True),
            args.expected_protocol_sha256)
        (output / 'independent-results.json').write_text(json.dumps(result, indent=2, sort_keys=True) + '\n')
        (output / 'independent-report.md').write_text(report(result))
        print(json.dumps({'valid': True, 'freshJvms': result['freshJvms'], 'queries': result['queries'],
            'matchedTreatmentQueryPairs': result['matchedTreatmentQueryPairs'],
            'bothScreensPassed': result['totalEffectEvidence']['bothPassed'], 'output': str(output)}))
    except BaseException as error:
        failure = {'valid': False, 'exception': type(error).__name__, 'message': str(error),
            'traceback': traceback.format_exc(), 'sourceFilesRead': SOURCE_FILES,
            'analysisScriptSha256': digest(__file__), 'acceptedComparisonEstimates': False}
        (output / 'independent-failure.json').write_text(json.dumps(failure, indent=2, sort_keys=True) + '\n')
        raise


if __name__ == '__main__':
    main()
